const express = require('express');
const { Pool } = require('pg');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Safe merge utility - only copies own enumerable string-keyed properties
// and blocks prototype pollution vectors
function safeMerge(target, source) {
  const blocked = ['__proto__', 'constructor', 'prototype'];
  for (const key of Object.keys(source)) {
    if (blocked.includes(key)) continue;
    if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      if (!target[key]) target[key] = Object.create(null);
      safeMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

// User preferences store - uses null-prototype objects to prevent prototype lookup
const userPreferences = Object.create(null);

// Session store - uses Map for safe key lookup
const sessions = new Map();

function generateSessionId() {
  return crypto.randomBytes(32).toString('hex');
}

// Verify a password against a stored scrypt hash of the form "<saltHex>:<hashHex>".
// Uses a slow KDF and a constant-time comparison.
function verifyPassword(password, stored) {
  if (typeof stored !== 'string' || !stored.includes(':')) {
    return false;
  }
  const [saltHex, hashHex] = stored.split(':');
  let salt;
  let expected;
  try {
    salt = Buffer.from(saltHex, 'hex');
    expected = Buffer.from(hashHex, 'hex');
  } catch (e) {
    return false;
  }
  if (salt.length === 0 || expected.length === 0) {
    return false;
  }
  const derived = crypto.scryptSync(password, salt, expected.length);
  if (derived.length !== expected.length) {
    return false;
  }
  return crypto.timingSafeEqual(derived, expected);
}

// Authentication middleware
function authenticate(req, res, next) {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId || !sessions.has(sessionId)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.user = sessions.get(sessionId);
  next();
}

// Authorization check - uses explicit hasOwnProperty check
function isAdmin(user) {
  const username = user.username;
  if (!Object.prototype.hasOwnProperty.call(userPreferences, username)) {
    return false;
  }
  const userRecord = userPreferences[username];
  return Object.prototype.hasOwnProperty.call(userRecord, 'isAdmin') && userRecord.isAdmin === true;
}

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }
  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid credential types' });
  }
  // Validate against database with parameterized query
  const result = await pool.query(
    'SELECT username, password_hash FROM users WHERE username = $1',
    [username]
  );
  if (result.rows.length === 0) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const user = result.rows[0];
  if (!verifyPassword(password, user.password_hash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const sessionId = generateSessionId();
  sessions.set(sessionId, { username: user.username, loginTime: Date.now() });
  res.json({ sessionId });
});

// User preferences update - safe merge that blocks prototype pollution
app.put('/api/preferences', authenticate, (req, res) => {
  const { preferences } = req.body;
  if (!preferences || typeof preferences !== 'object' || Array.isArray(preferences)) {
    return res.status(400).json({ error: 'Invalid preferences' });
  }
  if (!Object.prototype.hasOwnProperty.call(userPreferences, req.user.username)) {
    userPreferences[req.user.username] = Object.create(null);
  }
  safeMerge(userPreferences[req.user.username], preferences);
  res.json({ status: 'updated' });
});

// Standard data query - parameterized, safe
app.get('/api/data/:table', authenticate, async (req, res) => {
  const allowedTables = ['products', 'orders', 'categories'];
  const table = req.params.table;
  if (!allowedTables.includes(table)) {
    return res.status(400).json({ error: 'Invalid table' });
  }
  const limit = Math.min(Math.max(parseInt(req.query.limit) || 10, 1), 100);
  const offset = Math.max(parseInt(req.query.offset) || 0, 0);
  const result = await pool.query(
    `SELECT * FROM ${table} LIMIT $1 OFFSET $2`,
    [limit, offset]
  );
  res.json(result.rows);
});

// Admin analytics endpoint - restricted to pre-defined report queries only
app.post('/api/admin/analytics', authenticate, async (req, res) => {
  if (!isAdmin(req.user)) {
    return res.status(403).json({ error: 'Admin access required' });
  }
  const ALLOWED_REPORTS = {
    'sales_summary': 'SELECT date_trunc(\'month\', created_at) as month, SUM(total) as revenue FROM orders GROUP BY 1 ORDER BY 1',
    'top_products': 'SELECT p.name, COUNT(o.id) as order_count FROM products p JOIN orders o ON o.product_id = p.id GROUP BY p.name ORDER BY order_count DESC LIMIT 10',
    'category_breakdown': 'SELECT c.name, COUNT(p.id) as product_count FROM categories c LEFT JOIN products p ON p.category_id = c.id GROUP BY c.name'
  };
  const { reportType } = req.body;
  if (!reportType || !Object.prototype.hasOwnProperty.call(ALLOWED_REPORTS, reportType)) {
    return res.status(400).json({ error: 'Invalid report type', allowed: Object.keys(ALLOWED_REPORTS) });
  }
  try {
    const result = await pool.query(ALLOWED_REPORTS[reportType]);
    res.json({ rows: result.rows, rowCount: result.rowCount });
  } catch (err) {
    res.status(500).json({ error: 'Query execution failed' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(3000);
module.exports = app;
